"""Counting meanings per truth: the automorphism orbit of a permutation.

For a permutation f of {0,...,n-1}, the set of permutations sharing its *truth*
(cycle type) is exactly its conjugacy class -- an orbit under the whole symmetric
group. This demo computes, for small n, how many distinct meanings realize each
truth, confirming that the truth/meaning gap is a computable orbit cardinality.
"""

from __future__ import annotations

from itertools import permutations
from typing import Dict, List, Tuple


def cycle_type(perm: Tuple[int, ...]) -> Tuple[int, ...]:
    """Cycle type (lengths >= 2, descending) of a permutation given in one-line
    form: perm[i] is the image of i."""
    n = len(perm)
    seen = [False] * n
    lengths: List[int] = []
    for start in range(n):
        if seen[start]:
            continue
        length = 0
        x = start
        while not seen[x]:
            seen[x] = True
            x = perm[x]
            length += 1
        if length >= 2:
            lengths.append(length)
    return tuple(sorted(lengths, reverse=True))


def meanings_per_truth(n: int) -> Dict[Tuple[int, ...], int]:
    """Map each cycle type (truth) to the number of permutations of {0..n-1}
    realizing it (its distinct meanings)."""
    counts: Dict[Tuple[int, ...], int] = {}
    for perm in permutations(range(n)):
        ct = cycle_type(perm)
        counts[ct] = counts.get(ct, 0) + 1
    return counts


def main() -> None:
    for n in range(2, 6):
        print(f"n = {n}:  |Sym| = {sum(meanings_per_truth(n).values())}")
        for ct, count in sorted(meanings_per_truth(n).items()):
            label = "identity" if ct == () else f"cycle type {ct}"
            print(f"   truth [{label:>18}]  realized by {count:>3} meanings")
        print()
    print("Note: for n=3 the truth 'cycle type (2,)' has exactly 3 meanings,")
    print("matching the transpositions (0 1), (0 2), (1 2).")


if __name__ == "__main__":
    main()

