function TRANSPORT(e, f):
    e_inv <- invert(e)              # y -> x with e[x] = y
    for each y in image(e):
        result[y] <- e[ f[ e_inv[y] ] ]
    return result

function FUNCTORIAL(e, e', f):
    left  <- TRANSPORT(compose(e', e), f)
    right <- TRANSPORT(e', TRANSPORT(e, f))
    return left == right

