"""Algorithm: Conjugation transport (the isomorphism of isomorphisms).

Given an equivalence e : A -> B (a bijection, one-line/dict form) and a
permutation f of A, compute the transported permutation Phi_e(f) = e . f . e^{-1}
of B, and confirm functoriality Phi_{e'.e} = Phi_{e'} . Phi_e.
"""

from __future__ import annotations

from typing import Dict, Hashable, TypeVar

A = TypeVar("A", bound=Hashable)
B = TypeVar("B", bound=Hashable)


def invert(e: Dict[A, B]) -> Dict[B, A]:
    """Two-sided inverse of a bijection given as a dict."""
    return {v: k for k, v in e.items()}


def transport(e: Dict[A, B], f: Dict[A, A]) -> Dict[B, B]:
    """Phi_e(f)(y) = e(f(e^{-1}(y))) for y in the image of e."""
    e_inv = invert(e)
    return {y: e[f[e_inv[y]]] for y in e.values()}


def compose(g: Dict[B, "C"], e: Dict[A, B]) -> Dict[A, "C"]:  # type: ignore[name-defined]
    """(g . e)(x) = g(e(x))."""
    return {x: g[e[x]] for x in e}


def functorial(e: Dict[A, B], ep: Dict[B, "C"], f: Dict[A, A]) -> bool:  # type: ignore[name-defined]
    """Check Phi_{ep . e}(f) == Phi_{ep}(Phi_e(f))."""
    return transport(compose(ep, e), f) == transport(ep, transport(e, f))

algorithms.pseudocode:
function CYCLE_TYPE(f):
    seen <- empty set; lengths <- empty list
    for start in domain(f):
        if start in seen: continue
        len <- 0; x <- start
        while x not in seen:
            add x to seen; x <- f[x]; len <- len + 1
        if len >= 2: append len to lengths
    return sort(lengths, descending)

function SHARE_TRUTH(f, g):
    return CYCLE_TYPE(f) == CYCLE_TYPE(g)

function VERIFY_SDS(u, N):
    for m in 1..N, n in 1..N:
        if gcd(u(m), u(n)) != u(gcd(m,n)): return False
    return True

function MEANING_COUNT(n):
    counts <- empty map
    for perm in permutations(0..n-1):
        ct <- CYCLE_TYPE(perm)
        counts[ct] <- counts[ct] + 1
    return counts

