"""Algorithm: Strong divisibility verification and meaning-orbit counting.

Two procedures:
  1. verify_sds(u, N): decide whether a sequence obeys the strong divisibility
     law gcd(u_m, u_n) = u_{gcd(m,n)} on {1..N}. O(N^2) gcd evaluations.
  2. meaning_count(cycle_type_of, n): count how many permutations of {0..n-1}
     realize each truth (cycle type), i.e. the orbit size per truth. O(n!) but
     used only for small n to exhibit the exact truth->meaning multiplicity.
"""

from __future__ import annotations

from itertools import permutations
from math import gcd
from typing import Callable, Dict, List, Tuple


def verify_sds(u: Callable[[int], int], N: int) -> bool:
    """Check gcd(u_m, u_n) == u_{gcd(m,n)} for all 1 <= m, n <= N."""
    return all(
        gcd(u(m), u(n)) == u(gcd(m, n))
        for m in range(1, N + 1)
        for n in range(1, N + 1)
    )


def divides_implication(u: Callable[[int], int], N: int) -> bool:
    """Check the consequence m | n  =>  u_m | u_n for 1 <= m <= n <= N."""
    return all(
        u(n) % u(m) == 0
        for m in range(1, N + 1)
        for n in range(m, N + 1)
        if n % m == 0
    )


def _cycle_type(perm: Tuple[int, ...]) -> Tuple[int, ...]:
    n = len(perm)
    seen = [False] * n
    lengths: List[int] = []
    for s in range(n):
        if seen[s]:
            continue
        length = 0
        x = s
        while not seen[x]:
            seen[x] = True
            x = perm[x]
            length += 1
        if length >= 2:
            lengths.append(length)
    return tuple(sorted(lengths, reverse=True))


def meaning_count(n: int) -> Dict[Tuple[int, ...], int]:
    """For each truth (cycle type), the number of meanings (permutations of
    {0..n-1}) realizing it."""
    counts: Dict[Tuple[int, ...], int] = {}
    for perm in permutations(range(n)):
        ct = _cycle_type(perm)
        counts[ct] = counts.get(ct, 0) + 1
    return counts
